 "content": "from collections import Counter

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    for color in {v for row in grid for v in row if v != bg}:
        pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        # Extend a diagonal alignment in both directions, stopping at grid edges
        # or at a different existing object.
        for i, (r1, c1) in enumerate(pts):
            for r2, c2 in pts[i+1:]:
                dr, dc = r2-r1, c2-c1
                if abs(dr) == abs(dc) and dr != 0:
                    step_r = 1 if dr > 0 else -1
                    step_c = 1 if dc > 0 else -1
                    # Extrapolate from both endpoints along this diagonal.
                    for r, c, sr, sc in ((r1-step_r, c1-step_c, -step_r, -step_c),
                                         (r2+step_r, c2+step_c, step_r, step_c)):
                        while 0 <= r < h and 0 <= c < w and out[r][c] == bg:
                            out[r][c] = color
                            r += sr
                            c += sc
    return out
